const $=s=>document.querySelector(s), canvas=$('#farm'),ctx=canvas.getContext('2d');
const species={Emberling:{type:'Fire',color:'#f38e68',belly:'#ffd5ad',accent:'#d75e48',emoji:'🦊',worth:95},Bubbler:{type:'Water',color:'#78b9df',belly:'#d4f1f5',accent:'#438cb4',emoji:'🐸',worth:90},Mosskin:{type:'Grass',color:'#82ba79',belly:'#d8ebaa',accent:'#4d8c58',emoji:'🐰',worth:90},Zappup:{type:'Electric',color:'#f5cf61',belly:'#fff0a4',accent:'#d4a52f',emoji:'🐹',worth:105},Pufflet:{type:'Air',color:'#b8b2e8',belly:'#eeeaff',accent:'#8980c5',emoji:'🐥',worth:100},Pebblit:{type:'Earth',color:'#bf9b74',belly:'#ead7b7',accent:'#92704d',emoji:'🐻',worth:100},Bloomtail:{type:'Grass',color:'#eb9fc0',belly:'#ffe0e8',accent:'#d679a1',emoji:'🐱',worth:170},Frostfin:{type:'Water',color:'#91d9d3',belly:'#d8f8ed',accent:'#55aaa9',emoji:'🦭',worth:180},Cindercub:{type:'Fire',color:'#e78353',belly:'#ffcf94',accent:'#bd5238',emoji:'🐯',worth:175},Starwhisp:{type:'Crystal',color:'#c6a4e8',belly:'#f1e2ff',accent:'#9b71c5',emoji:'🦋',worth:240},Thundercub:{type:'Electric',color:'#f4d15b',belly:'#fff4ae',accent:'#bc982d',emoji:'🐲',worth:225},Moonmoss:{type:'Crystal',color:'#9bcdad',belly:'#e0f6d5',accent:'#6a9c8b',emoji:'🦄',worth:260},Clayhorn:{type:'Earth',color:'#d4a777',belly:'#f0d7b4',accent:'#9e744f',emoji:'🦏',worth:190},Cloudkip:{type:'Air',color:'#a9c9ee',belly:'#e1f3ff',accent:'#729bc5',emoji:'🐑',worth:175}};
const shopStock=['Emberling','Bubbler','Mosskin','Zappup','Pufflet','Pebblit'];
let state={coins:240,day:1,discoveries:0,creatures:[{id:1,name:'Emberling',type:'Fire',level:1},{id:2,name:'Mosskin',type:'Grass',level:1}],selected:[],eggs:[],journal:[],nextId:3,lastDay:Date.now(),sound:true,stock:[]};
function load(){try{const s=JSON.parse(localStorage.getItem('littleMonstersFarm'));if(s&&s.creatures)state={...state,...s};}catch(e){}if(!state.stock?.length)refreshStock();}
function save(){try{localStorage.setItem('littleMonstersFarm',JSON.stringify(state))}catch(e){}}
function refreshStock(){state.stock=[...shopStock].sort(()=>Math.random()-.5).slice(0,3);}
function speciesFor(c){return species[c.name]||species.Emberling}function price(c){const sp=speciesFor(c);return Math.round(sp.worth+(c.level-1)*25)}
function log(text){state.journal.unshift({text,time:Date.now()});state.journal=state.journal.slice(0,4);renderJournal();save()}
let toastTimer;function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function render(){ $('#coins').textContent=state.coins;$('#dayLabel').textContent='Day '+state.day;$('#farmCount').textContent=`${state.creatures.length} / 8`;$('#eggCount').textContent=state.eggs.length;$('#discoveries').textContent=state.discoveries;
 const grid=$('#creatureGrid');grid.innerHTML='';state.creatures.forEach(c=>{const sp=speciesFor(c),el=document.createElement('button');el.className='creature-card'+(state.selected.includes(c.id)?' selected':'');el.innerHTML=`<div class="sprite-mini">${sp.emoji}</div><strong>${c.name}</strong><small>Level ${c.level} · ${price(c)} 🪙</small><span class="type-tag ${c.type}">${c.type}</span>`;el.onclick=()=>select(c.id);grid.appendChild(el)});
 $('#shopList').innerHTML=state.stock.map(n=>{const s=species[n],cost=shopPrice(n);return `<div class="shop-item"><div class="shop-emoji">${s.emoji}</div><div class="shop-info"><strong>${n}</strong><small>${s.type} type · New friend</small></div><button class="buy-btn" data-buy="${n}">${cost} 🪙</button></div>`}).join('');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));
 $('#pairOne').textContent=state.selected[0]?speciesFor(state.creatures.find(c=>c.id===state.selected[0])||{}).emoji:'＋';$('#pairTwo').textContent=state.selected[1]?speciesFor(state.creatures.find(c=>c.id===state.selected[1])||{}).emoji:'＋';$('#selectionHelp').textContent=state.selected.length===0?'Choose two friends to breed':state.selected.length===1?'Choose one more friend': 'Ready for a little romance!';$('#breedBtn').disabled=state.selected.length!==2||state.eggs.length>=2||state.coins<40||state.creatures.length>=8;
 $('#breedBtn').textContent=state.eggs.length>=2?'Incubator is full':state.creatures.length>=8?'Farm is full':state.coins<40?'Need 40 🪙':'💕 Find a match · 40 🪙';renderEggs();renderJournal();drawFarm();save();}
function shopPrice(n){return ({Emberling:110,Bubbler:105,Mosskin:105,Zappup:120,Pufflet:115,Pebblit:110}[n]||115)}
function select(id){if(state.selected.includes(id)){state.selected=state.selected.filter(x=>x!==id)}else if(state.selected.length<2){state.selected.push(id)}else{state.selected=[state.selected[1],id]}render()}
function buy(n){if(state.creatures.length>=8)return toast('Your farm is full! Sell a friend first.');const cost=shopPrice(n);if(state.coins<cost)return toast('Not quite enough coins yet!');state.coins-=cost;const c={id:state.nextId++,name:n,type:species[n].type,level:1};state.creatures.push(c);state.stock=state.stock.filter(x=>x!==n);if(!state.stock.length)refreshStock();log(`A new ${n} joined your farm!`);toast(`${n} is home!`);render()}
function breed(){if(state.selected.length!==2||state.coins<40||state.eggs.length>=2||state.creatures.length>=8)return;const [a,b]=state.selected.map(id=>state.creatures.find(c=>c.id===id));if(!a||!b)return;state.coins-=40;
 let name=a.name;const different=a.type!==b.type;let rare=false;if(different&&Math.random()<.78){rare=true;const pair=[a.type,b.type].sort().join('-');const recipes={'Fire-Grass':'Bloomtail','Fire-Water':'Frostfin','Electric-Fire':'Thundercub','Air-Fire':'Cindercub','Crystal-Fire':'Starwhisp','Earth-Fire':'Clayhorn','Air-Grass':'Cloudkip','Crystal-Grass':'Moonmoss','Earth-Water':'Pebblit','Air-Water':'Frostfin','Crystal-Water':'Starwhisp','Electric-Grass':'Bloomtail','Electric-Water':'Thundercub','Air-Electric':'Cloudkip','Crystal-Electric':'Starwhisp','Earth-Grass':'Clayhorn','Air-Earth':'Cloudkip','Crystal-Earth':'Moonmoss','Air-Crystal':'Starwhisp','Crystal-Electric':'Starwhisp'};name=recipes[pair]||'Starwhisp';}
 else if(different){name=Math.random()<.5?a.name:b.name} else{name=Math.random()<.5?a.name:b.name}
 const offspring={name,type:species[name].type,level:1};state.eggs.push({id:state.nextId++,offspring,rare,ends:Date.now()+14000});state.selected=[];log(`💕 ${a.name} and ${b.name} have an egg!`);toast('A new egg is nestled in the incubator!');render();}
function renderEggs(){const area=$('#eggArea');if(!state.eggs.length){area.innerHTML='No eggs yet. The next generation starts here!';return}area.innerHTML=state.eggs.map(e=>{const remaining=Math.max(0,e.ends-Date.now()),pct=Math.max(0,Math.min(100,100-remaining/14000*100));return `<div class="eggrow"><div class="eggicon">🥚</div><div class="egginfo"><strong>${remaining<=0?'Ready to hatch!':'A little one is growing'}</strong><small>${remaining<=0?`A ${e.offspring.name} is waiting`:'Hatching in '+Math.ceil(remaining/1000)+' seconds'}</small><div class="progress"><i style="width:${pct}%"></i></div></div>${remaining<=0?`<button class="hatch-btn" data-hatch="${e.id}">Hatch!</button>`:''}</div>`}).join('');document.querySelectorAll('[data-hatch]').forEach(b=>b.onclick=()=>hatch(+b.dataset.hatch));}
function hatch(id){if(state.creatures.length>=8)return toast('Make room on your farm before hatching!');const i=state.eggs.findIndex(e=>e.id===id);if(i<0||state.eggs[i].ends>Date.now())return;const egg=state.eggs.splice(i,1)[0],c={...egg.offspring,id:state.nextId++};state.creatures.push(c);if(egg.rare&&!state.journal.some(x=>x.text.includes(`Discovered ${c.name}`))){state.discoveries++;log(`✨ Discovered ${c.name}, a rare new friend!`)}else log(`${c.name} hatched and joined the farm!`);toast(`${c.name} hatched! Welcome home!`);render();}
function openDetails(id){const c=state.creatures.find(x=>x.id===id);if(!c)return;const sp=speciesFor(c);$('#modal').innerHTML=`<div class="modal-art">${sp.emoji}</div><h2>${c.name}</h2><p><span class="type-tag ${c.type}">${c.type}</span> · Level ${c.level}<br>What a lovely little friend. Worth <b>${price(c)} coins</b>.</p><div class="modal-actions"><button class="secondary" id="closeModal">Keep cuddling</button><button class="action-btn sell-btn" id="sellFriend">Sell · ${price(c)} 🪙</button></div>`;$('#modalBg').classList.add('open');$('#closeModal').onclick=()=>$('#modalBg').classList.remove('open');$('#sellFriend').onclick=()=>sell(c.id)}
function sell(id){if(state.creatures.length<=1)return toast('Keep at least one friend on your farm!');const c=state.creatures.find(x=>x.id===id);if(!c)return;state.coins+=price(c);state.creatures=state.creatures.filter(x=>x.id!==id);state.selected=state.selected.filter(x=>x!==id);$('#modalBg').classList.remove('open');log(`${c.name} found a happy new home · +${price(c)} coins`);toast(`+${price(c)} coins · ${c.name} found a new home`);render()}
function renderJournal(){$('#logList').innerHTML=state.journal.slice(0,3).map(x=>`<div class="log-line"><b>✦</b><span>${x.text}</span></div>`).join('')||'<div class="log-line">A fresh start on a sunny day 🌼</div>'}

