const spots=[[198,263],[359,271],[537,267],[691,252],[284,188],[465,200],[600,174],[780,195]];let hitBoxes=[];
function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawFarm(){const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);
 // rolling meadow and sky
 const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#c7e9ef');sky.addColorStop(.52,'#e1f3ce');sky.addColorStop(.53,'#a9d47f');sky.addColorStop(1,'#91c56b');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 // distant soft hills
 ctx.fillStyle='#b9db9a';ctx.beginPath();ctx.moveTo(0,190);ctx.quadraticCurveTo(120,115,260,184);ctx.quadraticCurveTo(385,110,520,183);ctx.quadraticCurveTo(700,107,900,175);ctx.lineTo(900,280);ctx.lineTo(0,280);ctx.fill();
 ctx.fillStyle='#a5d084';ctx.beginPath();ctx.moveTo(0,220);ctx.quadraticCurveTo(170,160,325,218);ctx.quadraticCurveTo(550,154,710,221);ctx.quadraticCurveTo(800,185,900,207);ctx.lineTo(900,310);ctx.lineTo(0,310);ctx.fill();
 // clouds and sun
 ctx.fillStyle='#fff9dc';ctx.beginPath();ctx.arc(740,53,26,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f7d676';ctx.lineWidth=3;ctx.beginPath();ctx.arc(740,53,33,0,Math.PI*2);ctx.stroke();
 cloud(120,54,.85);cloud(397,73,.65);
 // far fence
 ctx.strokeStyle='#e9d8ae';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(0,194);ctx.lineTo(900,194);ctx.stroke();ctx.lineWidth=4;for(let x=14;x<900;x+=42){ctx.beginPath();ctx.moveTo(x,181);ctx.lineTo(x,209);ctx.stroke()}ctx.strokeStyle='#fff0cc';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,187);ctx.lineTo(900,187);ctx.stroke();
 // barn
